def transform(grid):
    g = [list(r) for r in grid]
    h, w = len(g), len(g[0])

    if any(all(v == 1 for v in row) for row in g):
        cuts = [i for i, row in enumerate(g) if all(v == 1 for v in row)]
        bounds = [-1] + cuts + [h]
        parts = [g[bounds[i] + 1:bounds[i + 1]] for i in range(4)]
        vertical = True
    else:
        cuts = [j for j in range(w) if all(g[i][j] == 1 for i in range(h))]
        bounds = [-1] + cuts + [w]
        parts = [[row[bounds[i] + 1:bounds[i + 1]] for row in g] for i in range(4)]
        vertical = False

    def trim_zero(part):
        cells = [(i, j) for i in range(len(part)) for j in range(len(part[0]))
                 if part[i][j] != 0]
        r0, r1 = min(i for i, j in cells), max(i for i, j in cells)
        c0, c1 = min(j for i, j in cells), max(j for i, j in cells)
        return [row[c0:c1 + 1] for row in part[r0:r1 + 1]]

    pattern = trim_zero(parts[0])
    green = trim_zero(parts[1])
    color_a = parts[2][0][0]
    color_b = parts[3][0][0]
    tile = [[color_a if v else color_b for v in row] for row in pattern]

    # Count separate green objects to determine the number of repetitions.
    gh, gw = len(green), len(green[0])
    unseen = {(i, j) for i in range(gh) for j in range(gw) if green[i][j]}
    copies = 0
    while unseen:
        copies += 1
        stack = [unseen.pop()]
        while stack:
            i, j = stack.pop()
            for ni, nj in ((i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)):
                if (ni, nj) in unseen:
                    unseen.remove((ni, nj))
                    stack.append((ni, nj))

    out = []
    if vertical:
        for k in range(copies):
            if k:
                out.append([color_b] * len(tile[0]))
            out.extend(row[:] for row in tile)
    else:
        for row in tile:
            line = []
            for k in range(copies):
                if k:
                    line.append(color_b)
                line.extend(row)
            out.append(line)
    return out
